create table sys_i18n (id varchar(64) not null, create_time timestamp(6), create_user varchar(64), event_comment varchar(512), event_name varchar(128), event_time timestamp(6), event_user varchar(64), tenant_id varchar(64), trx_id varchar(64), deleted boolean not null, description varchar(512), version bigint, code varchar(200) not null, content varchar(2000), locale_code varchar(32) not null, module varchar(64), scope varchar(16) not null check (scope in ('SYSTEM','USER')), primary key (id), constraint uk_sys_i18n_locale_code_tenant unique (locale_code, code, tenant_id, deleted));
create table sys_locale (id varchar(64) not null, create_time timestamp(6), create_user varchar(64), event_comment varchar(512), event_name varchar(128), event_time timestamp(6), event_user varchar(64), tenant_id varchar(64), trx_id varchar(64), deleted boolean not null, description varchar(512), version bigint, code varchar(32) not null, is_default boolean not null, name varchar(64), sort_no integer, status varchar(16) not null check (status in ('ENABLED','DISABLED')), primary key (id), constraint uk_sys_locale_code_tenant unique (code, tenant_id, deleted));
create index idx_sys_i18n_code on sys_i18n (code);
